// Normalise what Meta sent into the shape the rest of the flow uses.
//
// Two things matter here and neither is obvious from the docs:
//
// 1. We already answered 200. Meta retries a delivery it does not see
//    acknowledged in time, so anything slow belongs AFTER the response,
//    never before it.
// 2. One POST can carry several messages, and a retry carries the SAME
//    wamid. Emitting one item per message and letting message.wamid's
//    primary key absorb the duplicate is the whole idempotency design —
//    there is no separate dedupe table to drift out of sync.

const body = $input.first().json.body ?? $input.first().json;

const contacts = new Map(
  (body?.entry?.[0]?.changes?.[0]?.value?.contacts ?? []).map((c) => [c.wa_id, c.profile?.name])
);

const out = [];
for (const entry of body?.entry ?? []) {
  for (const change of entry.changes ?? []) {
    if (change.field !== 'messages') continue;
    for (const msg of change.value?.messages ?? []) {
      out.push({
        json: {
          wamid: msg.id,
          wa_number: msg.from,
          profile_name: contacts.get(msg.from) ?? null,
          // WhatsApp ships text, audio, sticker, document, location, buttons…
          // Anything unmapped arrives as null body and the reply step has
          // to handle it rather than assume a string was there.
          body: msg.text?.body ?? null,
          message_type: msg.type,
          // Meta's own timestamp, not ours — a retried webhook keeps it.
          sent_at: msg.timestamp ? new Date(Number(msg.timestamp) * 1000).toISOString() : null,
          received_at: new Date().toISOString(),
          status: 'received',
        },
      });
    }
  }
}

// A verification ping, a read receipt, or a message we already processed
// all land here with nothing to do. That is a normal outcome, not an error.
if (out.length === 0) {
  return [{ json: { status: 'ignored', reason: 'no_messages_in_payload' } }];
}

return out;
